bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const p=readFileSync('/opt/videobot/src/telegram/paidListingPublisher.mjs','utf8');
const m=readFileSync('/opt/videobot/src/telegram/paidMedia.mjs','utf8');
if(!p.includes("telegramApi('sendPaidMedia',paid)")&&!p.includes('telegramApi("sendPaidMedia",paid)'))process.exitCode=61;
else if(!m.includes("star_count:priceStars"))process.exitCode=62;
else if(/paidResult\??\.paid_media\??\.star_count/.test(p))process.exitCode=71;
else if(/paid_media\??\.star_count/.test(p))process.exitCode=72;
else if(/paidResult\??\.paid_media/.test(p))process.exitCode=73;
else if(/sendPaidMedia/.test(p))process.exitCode=74;
else process.exitCode=75;
else{
 const e=process.env;const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
 try{
 const q=await db.query("SELECT thumbnail_file_id,sample_file_id,paid_video_file_id,price_stars FROM videobot_listings WHERE listing_id=(SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1)",[4691]);
 if(q.rowCount!==1)process.exitCode=64;
 else{
 const r=q.rows[0];
 if(r.sample_file_id===r.paid_video_file_id||r.thumbnail_file_id===r.paid_video_file_id)process.exitCode=71;
 else if(Number(r.price_stars)!==10)process.exitCode=72;
 else console.log('LIVE_PAID_MEDIA_NATIVELY_LOCKED_DISTINCT_FILE_REFERENCES=PASS');
 }
 }finally{await db.end()}
}
JS
